# Parse the excel_data to build a structured summary
import re

lines = excel_data.strip().split('\n')
# Skip the header line "OBSERVATION: ..."
records = []
for line in lines:
    if line.startswith('OBSERVATION:'):
        continue
    # Extract cell values using regex: (row, col): value
    cells = re.findall(r'\((\d+),\s*(\d+)\):\s*([^\t]*)', line)
    if cells:
        row_num = int(cells[0][0])
        row_data = {int(c[1]): c[2].strip() for c in cells}
        records.append((row_num, row_data))

# Row 1 is header
header_row = None
data_rows = []
for row_num, row_data in records:
    if row_num == 1:
        header_row = row_data
    else:
        data_rows.append(row_data)

# Map column indices to header names
col_map = {i: header_row.get(i, f'Col{i}') for i in range(1, 8)}

# Build structured records
bookings = []
for rd in data_rows:
    booking = {}
    for i in range(1, 8):
        val = rd.get(i, '')
        if val == '[Empty Cell]':
            val = ''
        booking[col_map[i]] = val
    bookings.append(booking)

# Categorize
flights = [b for b in bookings if b.get('Type') == 'Flight']
hotels = [b for b in bookings if b.get('Type') == 'Hotel']
cars = [b for b in bookings if b.get('Type') == 'Car Rental']

confirmed_flights = [f for f in flights if f.get('Status') == 'confirmed']
cancelled_flights = [f for f in flights if f.get('Status') == 'cancelled']
confirmed_hotels = [h for h in hotels if h.get('Status') == 'confirmed']
cancelled_hotels = [h for h in hotels if h.get('Status') == 'cancelled']
confirmed_cars = [c for c in cars if c.get('Status') == 'confirmed']
cancelled_cars = [c for c in cars if c.get('Status') == 'cancelled']

# Unique users
all_users = sorted(set(b.get('User', '') for b in bookings))

# Total amounts
total_amount = sum(float(b.get('Amount', 0) or 0) for b in bookings)
confirmed_amount = sum(float(b.get('Amount', 0) or 0) for b in bookings if b.get('Status') == 'confirmed')
cancelled_amount = sum(float(b.get('Amount', 0) or 0) for b in bookings if b.get('Status') == 'cancelled')

summary = f"""
=== TRAVEL EXPENSES SPREADSHEET — TRIP CONTEXT ===

Total Bookings: {len(bookings)}
Total Users: {len(all_users)}

--- BREAKDOWN BY TYPE & STATUS ---

✈️  FLIGHTS: {len(flights)} total
   • Confirmed: {len(confirmed_flights)}
   • Cancelled: {len(cancelled_flights)}

🏨 HOTELS: {len(hotels)} total
   • Confirmed: {len(confirmed_hotels)}
   • Cancelled: {len(cancelled_hotels)}

🚗 CAR RENTALS: {len(cars)} total
   • Confirmed: {len(confirmed_cars)}
   • Cancelled: {len(cancelled_cars)}

--- FINANCIAL SUMMARY ---
   Total Amount (all):       ${total_amount:,.0f}
   Confirmed Bookings:       ${confirmed_amount:,.0f}
   Cancelled Bookings:       ${cancelled_amount:,.0f}

--- USERS ---
{chr(10).join('   • ' + u for u in all_users)}

--- CONFIRMED FLIGHTS ---"""

for f in confirmed_flights:
    summary += f"\n   {f['Booking ID']:10s} | {f['User']:20s} | {f['Route/Location']:12s} | ${float(f.get('Amount',0) or 0):,.0f}"

summary += "\n\n--- CONFIRMED HOTELS ---"
for h in confirmed_hotels:
    summary += f"\n   {h['Booking ID']:10s} | {h['User']:20s} | {h['Route/Location']:40s} | {h['Dates']:25s} | ${float(h.get('Amount',0) or 0):,.0f}"

summary += "\n\n--- CONFIRMED CAR RENTALS ---"
for c in confirmed_cars:
    summary += f"\n   {c['Booking ID']:10s} | {c['User']:20s} | {c['Route/Location']:40s} | {c['Dates']:25s} | ${float(c.get('Amount',0) or 0):,.0f}"

print(summary)

